// Exemplo de estrutura de interface (vtable em C)
struct file_operations {
    ssize_t (*read) (struct file *, char __user *, size_t, loff_t *);
    ssize_t (*write) (struct file *, const char __user *, size_t, loff_t *);
    int (*open) (struct inode *, struct file *);
    int (*release) (struct inode *, struct file *);
};

// Implementação específica para um dispositivo nulo (/dev/null)
static const struct file_operations null_ops = {
    .read    = read_null,
    .write   = write_null,
    .open    = open_null,
    .release = release_null,
};

// Struct 'Pai' / Base
struct device {
    const char *name;
    struct device_driver *driver;
};

// Struct 'Filha' contendo a Base
struct my_custom_dev {
    int custom_data;
    struct device dev; // Embed da struct base
};

// Recuperando o ponteiro do objeto 'Pai' a partir do 'Filho'
#define container_of(ptr, type, member) ({ \n    const typeof( ((type *)0)->member ) *__mptr = (ptr); \n    (type *)( (char *)__mptr - offsetof(type,member) );})
